import math

def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def relu(z):
    return max(0, z)

def sigmoid(z):
    return 1 / (1 + math.exp(-z))

def neuron(x, w, b, activation):
    return activation(dot(w, x) + b)

